member.remarks:
            Escapes the following characters:


& → &amp;

< → &lt;

> → &gt;

" → &quot;

' → &#39;

example.code:
var report = new ReportDocument("QA Summary Report");
report.Metadata = new ReportMetadata(); // Auto-populates
report.Context = ReportContext.FromPlanSetup(planSetup);

report.AddHeading("Results")
      .AddParagraph("All checks passed successfully.")
      .SaveToFile(@"C:\Reports\qa_summary.html");

remarks.para:
Example:

report.AddCollapsibleSection("Detailed Results", nested =>
{
    nested.AddParagraph("This content is hidden by default.");
    nested.AddDataTable(headers, rows);
});

member.returns:
0 if the points are collinear;
1 if clockwise orientation;
2 if counter-clockwise orientation.
